// Generated by `cargo xtask gen` from the tool's Rust output types. Do not edit.

export type Action =
	| "set_next"
	| "commit"
	| "rollback"
	| "stage"
	| "prepare"
	| "discard"
	| "finalize";

export type ActionView = {
	action: Action;
	/**
	 * The slot it acts on.
	 */
	slot: Slot;
	verdict: Verdict;
	/**
	 * Why it is refused (recab's message), when it is.
	 */
	reason: string | null;
	/**
	 * What it leaves, when it is ready.
	 */
	after: After | null;
};

export type After = {
	default_slot: Slot | null;
	next_boot: Slot | null;
	trial_pending: boolean;
	known_good_slot: Slot | null;
	rollback_slot: Slot | null;
};

export type BootSeal = {
	generation: string;
	kernel_release: string;
	architecture: string;
	protocol: number;
};

export type ChangeProgress = {
	id: string;
	action: string;
	package: string;
	report: SyncReport | null;
	/**
	 * Recipe /proc/self/io deltas, including reaped children and streams.
	 * Not physical SSD traffic; null means unmeasured.
	 */
	producer_io: { [key in string]: number } | null;
	/**
	 * Entire recab invocation through cleanup, including the Recipe subprocess.
	 * Available in the returned result; the persisted receipt predates cleanup.
	 * Final result serialization follows this observation.
	 */
	invocation_io: { [key in string]: number } | null;
	projection_bytes_written: number;
};

export type ChangeRecord = {
	id: string;
	/**
	 * `install`, `update`, `remove` or `edit`.
	 */
	action: string;
	/**
	 * The recipe's package, or the edited path.
	 */
	package: string;
	unix_time: number;
	/**
	 * Who asked for it, as the caller named itself (`--actor`): a label for
	 * the person reading, not an authenticated identity.
	 */
	actor: string | null;
};

export type DownloadProgress = {
	release: string;
	verified_files: number;
	total_files: number;
	verified_bytes: number;
	total_bytes: number;
	reused_files: number;
	producer_write_bytes: number;
	producer_cancelled_write_bytes: number;
	downloaded: boolean;
	/**
	 * False when a previous failed producer may have written unreported bytes.
	 */
	accounting_complete: boolean;
};

export type Finalization = {
	generation: Generation;
	seal: BootSeal;
	kernel_source: string;
	initrd_source: string;
	boot_bytes_written: number;
	boot_metadata_bytes_written: number;
	reused_boot_files: number;
	accounting_complete: boolean;
};

export type Generation = {
	id: string;
	inventory_digest: string;
	kernel_digest: string;
	initrd_digest: string | null;
};

export type Lifecycle = {
	state: LifecycleState;
	other: OtherSystem;
	/**
	 * A recab command holds the run lock right now. `None` when this reader
	 * may not open the lock file.
	 */
	working: boolean | null;
};

export type LifecycleState =
	| "stable"
	| "open"
	| "working"
	| "interrupted"
	| "ready"
	| "restart_set"
	| "on_trial"
	| "trial_failed"
	| "unusable";

export type OtherSystem = "copy" | "previous" | "next" | "unknown";

export type Preparation = {
	id: string;
	slot: Slot;
	source_slot: Slot;
	source_generation: string;
	revision: number;
	operation: string;
	phase: PreparationPhase;
	completed_steps: number;
	failure: string | null;
	/**
	 * Once synchronized, reopening must never reseed pending system changes.
	 */
	synchronized: boolean;
	synchronization: SyncReport | null;
	finalization: Finalization | null;
	change: ChangeProgress | null;
	last_change: ChangeProgress | null;
	/**
	 * Every change finished in this preparation, oldest first.
	 */
	changes: Array<ChangeRecord>;
};

export type PreparationPhase =
	| "intent"
	| "awaiting_synchronization"
	| "prepared"
	| "staging"
	| "finalizing"
	| "ready"
	| "interrupted";

export type Readiness = "empty" | "incomplete" | "ready" | "committed";

export type ReleaseSummary = {
	id: string;
	sequence: number;
	version: string;
	channel: string;
	total_bytes: number;
};

export type Slot = "A" | "B";

export type SlotView = {
	slot: Slot;
	/**
	 * The entry file, relative to the ESP (`loader/entries/<prefix>-a.conf`).
	 */
	entry: string;
	/**
	 * The directory of its kernel and initramfs, relative to the ESP.
	 */
	boot_dir: string;
	/**
	 * The entry's `root=` (`PARTUUID=...`), if it has one.
	 */
	root: string | null;
	/**
	 * The block device `root` names on this machine, if present.
	 */
	device: string | null;
	/**
	 * Every file the entry loads is on the ESP.
	 */
	bootable: boolean;
	/**
	 * The entry carries a trial's options (it was staged or scheduled and
	 * not yet committed).
	 */
	trial: boolean;
	generation: Generation | null;
	readiness: Readiness | null;
	generation_ready: boolean;
	seal: BootSeal | null;
	kernel: string | null;
	initrd: string | null;
};

export type Status = {
	updates: UpdateStatus | null;
	schema_version: number;
	active_slot: Slot;
	inactive_slot: Slot;
	/**
	 * A one-shot trial boot is set in the firmware and not yet taken.
	 */
	trial_pending: boolean;
	/**
	 * The slot the next boot starts: the trial slot, else the default.
	 */
	next_boot: Slot | null;
	default_slot: Slot | null;
	known_good_slot: Slot | null;
	/**
	 * The running slot is the known-good slot. After a trial boot this is
	 * false until it is committed; an uncommitted slot is left on next boot.
	 */
	committed: boolean;
	/**
	 * The slot `recab rollback` would select, if any.
	 */
	rollback_slot: Slot | null;
	/**
	 * The slot `set-next` scheduled and no boot has judged yet.
	 */
	scheduled_trial: Slot | null;
	/**
	 * How the last judged trial boot ended.
	 */
	last_trial: TrialRecord | null;
	entry_prefix: string;
	/**
	 * Each slot's entry, kernel directory and partition.
	 */
	slots: Array<SlotView>;
	/**
	 * What recab would make of each action now.
	 */
	actions: Array<ActionView>;
	preparation: Preparation | null;
	/**
	 * The same facts as one state a person can be told; see [`Lifecycle`].
	 */
	lifecycle: Lifecycle;
	recovery_reason: string | null;
};

export type SyncReport = {
	payload_bytes_written: number;
	payload_bytes_compared: number;
	range_writes: number;
	hole_bytes_punched: number;
	files_created: number;
	links_created: number;
	entries_removed: number;
	metadata_updates: number;
	identity_bytes_written: number;
	plan_bytes_written: number;
	/**
	 * A killed attempt can have written data before its counters were saved.
	 * Payload counters cover this attempt; false means earlier writes are unknown.
	 */
	accounting_complete: boolean;
	resumed: boolean;
	/**
	 * Filesystem metadata/journal traffic cannot be inferred from payload writes.
	 */
	filesystem_metadata_bytes: number | null;
	filesystem_journal_bytes: number | null;
	recab_state_bytes: number | null;
};

export type TrialRecord = {
	slot: Slot;
	/**
	 * The trial was healthy and committed; otherwise it was abandoned.
	 */
	committed: boolean;
	/**
	 * How startup ended, and the failed units if any.
	 */
	detail: string;
	unix_time: number;
};

export type UpdateStatus = {
	phase: string;
	highest_index: number;
	available: ReleaseSummary | null;
	download: DownloadProgress | null;
	pending_release: string | null;
	pending_preparation: string | null;
	last_error: string | null;
	/**
	 * P08 selects/validates the release; filesystem merging is owned by P09.
	 */
	merge_complete: boolean;
};

export type Verdict = "ready" | "no_change" | "refused";

export type Health = {
	/**
	 * The schema of this record.
	 */
	schema_version: number;
	init: InitSystem;
	/**
	 * How startup ended.
	 */
	startup: Startup;
	/**
	 * Startup ran to its end, healthy or not (`startup` is `running` or
	 * `failed`).
	 */
	finished: boolean;
	/**
	 * The init's own word: systemd's `is-system-running` answer, OpenRC's
	 * softlevel, or `timed out`.
	 */
	state: string;
	/**
	 * The units or services that failed (and, on OpenRC, crashed daemons),
	 * sorted, by bare name; listed even when startup did not finish.
	 */
	failed: Array<string>;
};

export type InitSystem = "systemd" | "openrc";

export type Startup = "running" | "failed" | "emergency" | "timed_out" | "inconclusive";

export type ErrorClass =
	| "permission"
	| "backend_unavailable"
	| "state_or_detection"
	| "partial_update"
	| "trial_failed";

export type ErrorPayload = {
	schema_version: number;
	/**
	 * `None` for an error without a class (exit status 1).
	 */
	class: ErrorClass | null;
	/**
	 * The exit status.
	 */
	code: number;
	message: string;
};

/** The slots, as every recab command and document spells them. */
export const SLOTS = ["A", "B"] as const;

/** The schema of the error a failed `--json` command prints. */
export const ERROR_SCHEMA_VERSION = 1 as const;

/** Each error class's exit status and the tag its text message starts with. */
export const ERROR_CLASSES = {
	backend_unavailable: { code: 20, tag: "RECAB_ERR_BACKEND" },
	partial_update: { code: 22, tag: "RECAB_ERR_PARTIAL_UPDATE" },
	permission: { code: 13, tag: "RECAB_ERR_PERMISSION" },
	state_or_detection: { code: 21, tag: "RECAB_ERR_STATE" },
	trial_failed: { code: 23, tag: "RECAB_ERR_TRIAL_FAILED" },
} as const;

/** Where recab keeps its state on an installed system. */
export const STATE_FILE = "/var/lib/recab/state.json" as const;

/** Where recab keeps its audit log (JSON lines) on an installed system. */
export const AUDIT_FILE = "/var/lib/recab/audit.log" as const;

/** How long a trial waits for startup to finish. */
export const TRIAL_TIMEOUT_SECS = 900 as const;
